JNS equ 0x0D
HLT equ 0x01
jmp start ;переходим к началу
image_right db  ;правая часть изображения без последних двух байт
                        0b10101001, 0b00110010,
0b10001010, 0b10101010, 0b10101001, 0b00001010,
0b11101010, 0b10101110, 0b11001011, 0b00110010,
0b10001010, 0b10100010, 0b10101101, 0b00000000,
0b11101010, 0b11100010, 0b10101001, 0b00100010
image_right_end equ $

loop1: ;самый верхний цикл - перебор байт
  dec d ;следующий байт
  loop1_jmp: js next ;если они закончились, прекращаем цикл
  ldi b, 0b00000001 ;восстанавливаем маску
  st b, mask
  ld b, bank ;читаем байт (переключаемся на первый банк, т. к. левая часть там)
  ldi c, 1
  st c, bank
  ld a, d
  st b, bank ;восстанавливаем банк
  loop2: ;цикл уровнем ниже - перебор банков
    ld c, bank ;читаем банк
    dec c ;следующий банк
    st c, bank ;сохраняем
    ldi c, 0x80 ;восстанавливаем адрес
    st c, addr2
    loop3: ;цикл около нижнего уровня - перебор адресов в банке
      ld c, addr2 ;читаем адрес
      ldi b, 0x40 ;уменьшаем
      sub c, b
      jc loop2 ;если перебрали все адреса, уменьшаем банк
      st c, addr2 ;сохраняем новый адрес
      ld b, mask ;читаем маску
      and b, a ;если наткнулись на бит, рисуем пиксель
      jnz draw_pixel
      jmp loop3_end ;иначе сразу идём в конец
void db 0
in_out db 0 ;ввод-вывод (ничего не подключаем)
bank db 128 ;банк (изначально 112, чтобы цикл начался с правильного места)

draw_pixel: ;рисование пикселя
  st d, save ;сохраняем регистр d
  ld d, addr1 ;читаем адрес
  add d, c ;прибавляем адрес перебора
  ldi c, 32 ;счётчик
  loop4: ;цикл нижнего уровня - отрисовка пикселя
    rnd b ;генерирум случайный набор бит для эффектности
    st b, d ;сохраняем
    inc d ;следующий адрес
    dec c ;продолжаем, пока не заполним всю ячейку
    jnz loop4
  ld d, save ;восстанавливаем регистр d
  loop3_end:
    ld b, mask ;читаем маску
    shl b ;сдвигаем
    jc loop1 ;если сдвинули за пределы байта, переходим к верхнему циклу
    st b, mask ;сохраняем маску
    jmp loop3 ;переходим к нижнему циклу

next:
  ldi a, JNS ;меняем условие перехода
  st a, loop1_jmp
  ldi a, end ;меняем адрес перехода
  st a, loop1_jmp + 1
  ldi a, 0x80 + 0x20 ;меняем адрес сохранения (+ 0x20 - отражение позиции)
  st a, addr1
  ldi a, 128 ;восстанавливаем банк
  st a, bank
  ldi d, image_left_end ;адрес чтения левого изображения
  jmp loop1 ;переходим на вывод
end:
  ldi a, 15 ;сохраняем hlt в самый левый угол, чтобы не мешала полоска
  st a, bank
  ldi a, HLT
  st a, 0xE0
  jmp 0xE0 ;прыгаем на завершение программы
save db 0 ;сохранение важных значений
mask db 0 ;маска
addr1 db 0x80 ;адрес уровня 1
addr2 db 0 ;адрес уровня 2
void2 db 0, 0, 0, 0, 0, 0
image_left db  ;левая часть изображения (отражена, как и сама память)
0b11101110, 0b11100000, 0b11100111, 0b00111000,
0b10100100, 0b00100000, 0b00100101, 0b00001000,
0b11100100, 0b00100000, 0b11100101, 0b00001000,
0b00100100, 0b00100000, 0b00101111, 0b10001000,
0b00100100, 0b11100000, 0b11101000, 0b10001000
image_left_end equ $
start:
  ldi a, 0b11100110 ;восстанавливаем последние 2 байта правого изображения
  st a, b
  ldi a, 0b11101010
  st a, 0x01
  ldi d, image_right_end ;адрес чтения правого изображения
  jmp loop1 ;переходим на вывод



